import {brands,brandMethod} from './brands.js';
import {orderComparison} from './delivery.js';
import {sources,updates} from './content.js';
const $=id=>document.getElementById(id),fmt=(n,d=0)=>n.toLocaleString('ko-KR',{maximumFractionDigits:d}),money=n=>`${n<0?'−':''}${fmt(Math.abs(n))}만원`;
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
export function brandPicker(industry,onSelect){const list=brands[industry],previous=$('brand').value;$('brand').innerHTML=list.map(b=>`<option value="${b.id}">${b.keyword}</option>`).join('');if(list.some(b=>b.id===previous))$('brand').value=previous;const chosen=$('brand').value;
 $('brandOptions').innerHTML=list.map(b=>`<button class="brand-option" data-brand="${b.id}" type="button" aria-pressed="${b.id===chosen}"><span>평균매출 상위 ${b.rank}</span><strong>${b.keyword}</strong><small>참고 연매출 ${money(b.annualSales)}</small><em>${b.sourceKind==='official'?'2024 실적 · 공정위 공표':'공개 집계 · 연도 혼재'}</em></button>`).join('');
 $('brandOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('brand').value=b.dataset.brand;$('brandOptions').querySelectorAll('button').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));onSelect();});
}
export function paintBrandSummary(s){const b=s.brandData;if(!b)return;$('brandSummary').innerHTML=`<div><span>기존 가맹점 통계</span><strong>연 ${money(b.annualSales)}</strong><small>${b.period}${b.published?' · 발표 '+b.published:''}</small></div><b>→</b><div><span>내 가게 가정</span><strong>월 ${money(s.sales)}</strong><small>기본 반영률 ${s.salesCapture}% + 지역·규모·전략${$('sales').dataset.override==='true'?' · 매출 직접 수정':''}</small></div><p>평균매출은 이익이나 신규 매장의 예상 매출이 아닙니다. 비용은 해당 브랜드의 실제 계약이 아닌 업종 공통 가정입니다. ${b.sourceKind==='secondary'?'분식 수치는 보조 집계이며 원문 실적연도 재대조가 필요합니다.':''} ${link(b.source.url,'선정 근거')}</p>`;}
function feeRows(r){return [['중개료',r.deliveryCommission],['점주 배달비',r.deliveryLogistics],['배달 결제료',r.deliveryPaymentCost],['배달 광고비',r.deliveryAdvertising]].map(([name,v])=>`<div><span>${name}</span><b>${money(v)}</b></div>`).join('');}
export function paintFeePreview(s,r){const rate=r.deliverySales?r.platformBurden/r.deliverySales*100:0;$('feePreview').innerHTML=`<div class="fee-head"><span>주문이 늘면, 이 비용도 늘어납니다</span><strong>${money(r.platformBurden)}<small>월 배달 관련 총부담</small></strong></div><div class="fee-breakdown">${feeRows(r)}</div><p>기준 월 매출 ${money(r.sales)} 중 배달 ${s.deliveryShare}% · 배달 매출 대비 비용 ${fmt(rate,1)}%. 원재료·인건비·임대료는 별도입니다.</p><small>계절변동 제외 가상 계산. 배달 결제료는 카드수수료 항목에 한 번만 반영하며 위 합계는 설명용 재분류입니다. 모든 값은 부가세 제외 비용 가정입니다.</small>`;}
export function paintRunBurden(s,r){$('runDelivery').innerHTML=`<span>이번 달 / 배달의 이면</span><strong>배달 매출 ${money(r.deliverySales)} → 관련 비용 ${money(r.platformBurden)}</strong><div class="fee-breakdown">${feeRows(r)}</div><small>배달 비중 ${s.deliveryShare}% · 주문 약 ${fmt(r.orders)}건 · 수수료·배달비·결제·광고 합계. 원재료와 고정비 차감 전.</small>`;}
export function deliveryResult(s){const sum=k=>s.records.reduce((v,r)=>v+r[k],0),total=sum('platformBurden'),deliverySales=sum('deliverySales');return `<div class="delivery-result"><p>배달 매출만으로는 보이지 않는 비용</p><strong>${money(total)}</strong><span>${s.month}개월 누적 중개료·점주 배달비·배달 결제료·배달 광고비</span><div class="fee-breakdown">${feeRows({deliveryCommission:sum('deliveryCommission'),deliveryLogistics:sum('deliveryLogistics'),deliveryPaymentCost:sum('deliveryPaymentCost'),deliveryAdvertising:sum('deliveryAdvertising')})}</div><p>배달 매출 ${money(deliverySales)}의 ${fmt(deliverySales?total/deliverySales*100:0,1)}%가 이 네 항목에 쓰였습니다. 이 비율은 게임 기록이며 실제 브랜드나 업계의 평균이 아닙니다.</p><button type="button" id="resultDeliveryLink" class="action-alt">배달수수료 현실 이야기 읽기 →</button></div>`;}
export function deliveryStoryMarkup(){return `<div class="interactive-chart delivery-explainer"><span>가상 주문 1건 / 비용을 하나씩 펼쳐보세요</span><h4>중개수수료가 전부일까요?</h4><p>고객의 무료배달과 점주의 배달비 0원은 같은 말이 아닙니다. 결제료·배달비·광고비까지 따로 확인해야 합니다.</p><div class="order-controls"><label for="orderAmount">주문금액 (원)</label><input id="orderAmount" type="number" min="5000" max="100000" step="1000" value="25000"/><label for="orderFee">중개료 (%)</label><input id="orderFee" type="number" min="0" max="30" step=".1" value="7.8"/><label for="orderDelivery">점주 배달비 (원)</label><input id="orderDelivery" type="number" min="0" max="20000" value="2900"/><label for="orderAd">광고비 가정 (%)</label><input id="orderAd" type="number" min="0" max="25" step=".1" value="0"/></div><div id="orderChart"></div><p id="orderCaption" class="order-answer"></p><small>부가세 제외 주문금액·비용 기준. 원재료 40%, 배달 결제 3%, 인건비 배분 3,000원, 기타 배분 1,500원. 비율·비용은 가정이며 세후 순이익이 아닙니다. 실제 플랫폼 요금표와 별개인 학습용 모형입니다.</small></div><div class="interactive-chart fee-history"><span>2024 → 이후 확인한 정책</span><h4>중개료가 2%p 내려도<br>총부담은 같을 수 있습니다.</h4><label for="historyTicket">가상 주문금액 <b id="historyTicketValue">25,000원</b></label><input id="historyTicket" type="range" min="10000" max="50000" value="25000" step="1000"/><div id="feeHistoryComparison"></div><p id="feeHistoryConclusion"></p><small>2024년 정부 발표 당시 기본 조건(중개 9.8%, 배달비 범위 상단 2,900원)과 현재 확인되는 상위 구간 조건(7.8%, 배달비 범위 상단 3,400원)을 골라 계산했습니다. 결제료 3%는 동일한 가정, 광고비 0원, VAT 제외입니다. 지역·매출 구간이 다른 공시 범위의 가상 비교로, 실제 동일 매장의 정책 효과나 모든 업체의 요금 인상을 뜻하지 않습니다.</small><div class="source-links">${link(sources.delivery2024.url,'2024년 정부 최종 상생안')}${link(sources.baemin.url,'배민 공식 요금 안내')}${link(sources.coupangCurrent.url,'쿠팡이츠 공식 요금 안내')}</div></div><div class="interactive-chart platform-policy"><span>2026.10.19 확인 / 플랫폼별 조건 구분</span><div class="policy-grid"><div><h4>배민배달</h4><p>중개 2.0~7.8%, 점주 배달비 1,900~3,400원 범위(VAT 별도). 매출 규모를 3개월간 산정하고 3개월 단위로 적용합니다. 지역별 할인과 신규 가게 조건은 별도입니다.</p>${link(sources.baemin.url,'공식 상세표')}</div><div><h4>쿠팡이츠 음식배달</h4><p>같은 중개·배달비 구간표지만, 기본 정산 후 해당 월 실질 구간에 따른 차액을 환급합니다. 포장 지원은 음식배달과 별도 정책입니다.</p>${link(sources.coupangCurrent.url,'공식 상세표')}<br>${link(sources.coupangSettlement.url,'정산 정책')}</div></div><p class="reality-caption">표에 없는 요기요·공공배달앱과 개별 특약에는 위 요율을 자동 적용하지 않습니다. 게임은 특정 플랫폼 계약을 재현하지 않습니다.</p></div>`;}
export function wireDeliveryStory(){const ids=['orderAmount','orderFee','orderDelivery','orderAd'];const draw=()=>{if(ids.some(id=>!$(id).value||!$(id).checkValidity())){$('orderCaption').textContent='입력 범위를 확인하세요.';return;}const amount=Number($('orderAmount').value),fee=amount*Number($('orderFee').value)/100,del=Number($('orderDelivery').value),ad=amount*Number($('orderAd').value)/100,payment=amount*.03,material=amount*.4,left=amount-material-fee-del-payment-ad-3000-1500;const rows=[['원재료',material],['점주 배달비',del],['중개료',fee],['배달 결제료',payment],['배달 광고비',ad],['인건비 배분',3000],['기타 배분',1500],['점주 잔여액',left]];$('orderChart').innerHTML=rows.map(([k,v])=>`<div class="order-row"><span>${k}</span><div><i style="width:${Math.min(100,Math.abs(v)/amount*100)}%"></i></div><b>${fmt(v)}원</b></div>`).join('');$('orderCaption').textContent=`비용 배분 후 잔여액 ${fmt(left)}원. 배달 관련 네 항목만 ${fmt(fee+del+payment+ad)}원 (${fmt((fee+del+payment+ad)/amount*100,1)}%)입니다. 세후 순이익이 아닙니다.`;};ids.forEach(id=>$(id).oninput=draw);draw();wireFeeHistory();}
function wireFeeHistory(){const draw=()=>{const ticket=Number($('historyTicket').value),c=orderComparison(ticket);$('historyTicketValue').textContent=fmt(ticket)+'원';$('feeHistoryComparison').innerHTML=[['2024 기본 조건 예시',c.old,'9.8%','2,900원'],['최신 상위 구간 예시',c.now,'7.8%','3,400원']].map(([label,v,rate,del])=>`<div><span>${label}</span><strong>${fmt(v.total)}<small>원</small></strong><p>중개 ${rate} = ${fmt(v.commission)}원<br>배달비 ${del}<br>결제료 가정 ${fmt(v.payment)}원</p></div>`).join('');$('feeHistoryConclusion').textContent=c.delta===0?'중개료는 500원 줄고, 배달비는 500원 늘어 총부담은 같습니다.':`이 가상 조건에서는 총부담이 ${fmt(Math.abs(c.delta))}원 ${c.delta>0?'늘어납니다':'줄어듭니다'}. 주문금액에 따라 결과가 달라집니다.`;};$('historyTicket').oninput=draw;draw();}
export function paintUpdates(){ $('after2024').innerHTML=`<div class="update-heading"><span>취재 이후의 변화</span><h3>가게의 매출이 늘었다고,<br>사장님의 몫도 늘었을까요?</h3><p>아래는 2024년 취재 대상자의 근황이 아닌, 이후 발표된 제도와 경제지표입니다. 최신 발표 자료도 실적은 2024년 또는 2025년일 수 있습니다.</p></div><div class="update-chapters">${updates.map((u,i)=>`<article><b>0${i+1}</b><span>${u.period}</span><h4>${u.title}</h4><strong>${u.number}</strong><p>${u.text}</p>${link(sources[u.source].url,sources[u.source].label)}</article>`).join('')}</div><div class="report-timeline"><div><b>2024.09</b><p>중앙일보 자영업 리포트<br>현장의 비용·경쟁·노동 부담</p></div><div><b>2024.11 → 2025</b><p>정부 상생안 발표<br>이후 플랫폼별 차등요금제 시행</p></div><div><b>2026.04</b><p>공정위 가맹사업 통계 발표<br>가맹점 매출의 대상 기간은 2024년</p></div><div><b>2026.11</b><p>10월 고용동향 발표<br>고용원 유무에 따라 다른 변화</p></div></div><p class="update-footnote">수치가 늘거나 줄었다는 사실만으로 하나의 정책 효과나 전체 자영업자의 처지를 단정하지 않습니다. 아래 비교 그래프에서 대상 집단·실적연도·발표일을 함께 확인하세요.</p>`;
 $('brandSources').innerHTML=`<details><summary>키워드에 대응하는 브랜드와 선정 기준 확인</summary><p>${brandMethod}</p><div class="tablewrap"><table><thead><tr><th>업종</th><th>선택 키워드</th><th>자료상 브랜드</th><th>연평균 매출 (만원)</th><th>대상 기간·검증</th><th>출처</th></tr></thead><tbody>${Object.entries(brands).flatMap(([category,list])=>list.map(b=>`<tr><td>${({chicken:'치킨',cafe:'카페',store:'편의점',snack:'분식'})[category]}</td><td>${b.keyword}</td><td>${b.name}</td><td>${fmt(b.annualSales,1)}</td><td>${b.period}</td><td>${link(b.source.url,b.sourceKind==='official'?'공정위 공표, '+b.page+'쪽':'보조 집계')}</td></tr>`)).join('')}</tbody></table></div></details>`;}
